using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using SBCCashier.Web.Models;using SBCCashier.Web.Services;
namespace SBCCashier.Web.Pages.Students;
public sealed class IndexModel:PageModel{private readonly CashierStore _store;public IReadOnlyList<Student> Students{get;private set;}=[];public string? ErrorMessage{get;private set;}[BindProperty]public Student NewStudent{get;set;}=new();public IndexModel(CashierStore store)=>_store=store;public void OnGet()=>Load();public IActionResult OnPostCreate(){if(string.IsNullOrWhiteSpace(NewStudent.StudentId)||string.IsNullOrWhiteSpace(NewStudent.FullName)){ErrorMessage="Student ID and full name are required.";Load();return Page();}try{_store.AddStudent(NewStudent);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}private void Load()=>Students=_store.Students;}
